transforms.code:
rows = []
for r in (value or []):
	if r.get("ContainerId") is None:
		continue
	nm = "Container #" + str(r.get("ContainerId"))
	if r.get("ContainerItemPartNumber"):
		nm = nm + "  -  " + r.get("ContainerItemPartNumber")
	rows.append({"holdEventId": r.get("HoldEventId"), "lotId": 0, "target": nm, "holdTypeCode": r.get("HoldTypeCode") or "", "reason": r.get("Reason") or ""})
return rows

config.script:
d = self.view.custom.placeDraft
lotName = (d.get("lotName") or "").strip()
containerId = BlueRidge.Common.Util.toIntOrNone(d.get("containerId"))
holdTypeCodeId = d.get("holdTypeCodeId")
reason = (d.get("reason") or "").strip() or None
if holdTypeCodeId is None:
	BlueRidge.Common.Ui.notifyResult({"Status": False, "Message": "Select a hold type."}, "Place Hold")
	return
if not lotName and containerId is None:
	BlueRidge.Common.Ui.notifyResult({"Status": False, "Message": "Enter a LOT name or a Container Id."}, "Place Hold")
	return
if lotName and containerId is not None:
	BlueRidge.Common.Ui.notifyResult({"Status": False, "Message": "Enter only one of LOT name or Container Id, not both."}, "Place Hold")
	return
lotId = None
if lotName:
	lot = BlueRidge.Lots.Lot.getByName(lotName)
	if not lot or lot.get("Id") is None:
		BlueRidge.Common.Ui.notifyResult({"Status": False, "Message": "No LOT found named '" + lotName + "'."}, "Place Hold")
		return
	lotId = lot.get("Id")
result = BlueRidge.Quality.Hold.place(holdTypeCodeId, lotId=lotId, containerId=containerId, reason=reason)
BlueRidge.Common.Ui.notifyResult(result, "Hold placed")
if result and result.get("Status"):
	self.view.custom.placeDraft = {"lotName": "", "containerId": "", "holdTypeCodeId": None, "reason": ""}
	self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1
	if lotId is not None:
		cons = BlueRidge.Quality.Hold.listAssociatedContainers(lotId) or []
		lines = []
		for c in cons:
			lines.append("- Container #" + str(c.get("ContainerId")) + "  " + (c.get("ItemPartNumber") or "") + "  (" + (c.get("ContainerStatusCode") or "") + ", " + (c.get("CurrentLocationName") or "") + ")")
		self.view.custom.containerAdvisory = {"lotName": lotName, "containers": cons, "summary": "\n".join(lines)}
		if len(cons) > 0:
			BlueRidge.Common.Ui.notifyResult({"Status": True, "Message": str(len(cons)) + " associated container(s) - review whether they need holding too."}, "Container advisory")

messageHandlers.script:
he = payload.get("holdEventId")
cur = self.view.custom.releaseDraft or {}
self.view.custom.releaseDraft = {"holdEventId": (str(he) if he is not None else ""), "releaseRemarks": (cur.get("releaseRemarks") or "")}

lid = payload.get("lotId")
if lid is None:
	return
lid = int(lid)
cur = [int(x) for x in (self.view.custom.bulkSelectedLotIds or [])]
if lid in cur:
	cur.remove(lid)
else:
	cur.append(lid)
self.view.custom.bulkSelectedLotIds = cur
